/**
 * Whether Storybook is being freshly created or upgraded. Used to tailor the rerun instructions and
 * commands surfaced to the user when a minimum-release-age gate blocks the install.
 */
export type StorybookInstallContext = 'create' | 'upgrade';

/**
 * The core set of package name patterns that Storybook needs to be able to install in order for a
 * `create` or `upgrade` to succeed. Patterns may contain glob-style `*` wildcards.
 */
export const STORYBOOK_PACKAGE_PATTERNS = [
  'storybook',
  '@storybook/*',
  'eslint-plugin-storybook',
  '@chromatic-com/storybook',
];

/** Escape characters that carry special meaning within a regular expression. */
const escapePatternForRegex = (pattern: string) => pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Turn a package name pattern (which may contain glob-style `*` wildcards) into a `RegExp`. */
const packagePatternToRegex = (pattern: string) =>
  new RegExp(`^${escapePatternForRegex(pattern).replace(/\\\*/g, '.*')}$`);

/**
 * Determine whether the provided list of configured package patterns already excludes every core
 * Storybook package from a minimum-release-age gate. Returns `true` only if each of the
 * {@link STORYBOOK_PACKAGE_PATTERNS} is matched by at least one configured pattern.
 */
export const hasStorybookMinimumAgeExclusions = (configuredPatterns: string[]) => {
  return STORYBOOK_PACKAGE_PATTERNS.every((storybookPattern) =>
    configuredPatterns.some((configuredPattern) =>
      packagePatternToRegex(configuredPattern).test(storybookPattern)
    )
  );
};

/**
 * Parse a configuration value that is expected to be a positive integer (e.g. a minimum release age
 * in minutes). Returns the parsed integer, or `null` when the value is missing, empty, one of the
 * common "disabled" sentinels (`undefined`, `null`, `false`), or not a positive integer.
 */
export const parsePositiveIntegerConfigValue = (
  value: string | null | undefined
): number | null => {
  const normalizedValue = value?.trim() ?? '';

  if (
    !normalizedValue ||
    normalizedValue === 'undefined' ||
    normalizedValue === 'null' ||
    normalizedValue === 'false'
  ) {
    return null;
  }

  const parsedValue = Number.parseInt(normalizedValue, 10);

  if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
    return null;
  }

  return parsedValue;
};

/** Parse a release time value into a `Date`, returning `null` for anything that isn't a valid date. */
export const parseReleaseTime = (value: unknown): Date | null => {
  if (typeof value !== 'string' || value.length === 0) {
    return null;
  }

  const releaseTime = new Date(value);

  return Number.isNaN(releaseTime.getTime()) ? null : releaseTime;
