/**
 * Normalize an unknown value into a plain `Record<string, string>` mapping version strings to their
 * release times. Returns `null` for non-object inputs (strings, arrays, `null`, `undefined`) and
 * omits entries whose value isn't a non-empty string.
 */
export const parsePackageTimeMap = (value: unknown): Record<string, string> | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const timeMap: Record<string, string> = {};

  for (const [version, releaseTime] of Object.entries(value)) {
    if (typeof releaseTime === 'string' && releaseTime.length > 0) {
      timeMap[version] = releaseTime;
    }
  }

  return timeMap;
};

/** Compute the age, in whole minutes, between a published-at date and a reference date. */
export const getAgeInMinutes = (now: Date, publishedAt: Date) => {
  return Math.floor((now.getTime() - publishedAt.getTime()) / 60_000);
};

